// Issue #31: no route may put the content of an exception into the body of its answer.
const SECRET = 'SQLITE_BUSY: database is locked at /srv/data/booking.db';
const boom = async () => { throw new Error(SECRET); };
const failingDeps = {
  rooms: { all: boom, find: boom, update: boom },
  bookings: { forRoom: boom, create: boom, cancel: boom },
  invoices: { find: boom },
  mailer: { sendReminders: boom },
  users: { find: boom },
  db: { ping: boom },
};
// A request that passes the checks of every route, so that each one reaches its store.
const validReq = {
  params: { id: 'r1' },
  body: { roomId: 'r1', date: '2026-12-01', name: 'Maple' },
  query: { date: '2026-12-01' },
  user: { id: 'u1' },
};
const fixed500 = { status: 500, body: { error: INTERNAL_ERROR } };
const expectedOnFailure = {
  'reminders-send': { status: 502, body: { message: 'could not send the reminders' } },
};

for (const name of Object.keys(routes)) {
  test(`${name} answers a fixed text when its store fails, and logs the error`, async () => {
    const before = logged.length;
    const r = await dispatch(name, validReq, failingDeps);
    assert.deepEqual(r, expectedOnFailure[name] ?? fixed500);
    assert.equal(logged.length, before + 1);
    assert.equal(logged.at(-1).where, name);
    assert.match(logged.at(-1).detail, /SQLITE_BUSY/);
  });

  test(`${name} does not leak a thrown value that is not an Error`, async () => {
    const thrower = async () => { throw 'ENOENT: /srv/data/booking.db'; };
    const stringDeps = Object.fromEntries(
      Object.entries(failingDeps).map(([k, v]) => [k, Object.fromEntries(Object.keys(v).map((m) => [m, thrower]))]),
    );
    const r = await dispatch(name, validReq, stringDeps);
    assert.ok(r.status >= 500);
    assert.doesNotMatch(JSON.stringify(r.body), /ENOENT|booking\.db/);
    assert.match(logged.at(-1).detail, /ENOENT/);
  });
}

